from pathlib import Path
p=Path('/output')
p.joinpath('fit_hmm.py').write_text('''import numpy as np,time

def softmax(a):
 a=a-a.max(-1,keepdims=True);e=np.exp(a);return e/e.sum(-1,keepdims=True)
def logits(p): return np.log(np.maximum(p,1e-9))
def predict(T,par):
 E,A,pi=map(softmax,par); B,N=T.shape; b=np.broadcast_to(pi,(B,len(pi))).copy();q=[]
 for t in range(N+1):
  q.append(b@E)
  if t<N:
   b=b*E[:,T[:,t]].T;b=b/b.sum(1,keepdims=True);b=b@A
 return np.stack(q,1)
def lossgrad(T,P,par):
 E,A,pi=map(softmax,par); B,L,V=P.shape;K=len(pi);b=np.broadcast_to(pi,(B,K)).copy();bs=[];ws=[];qs=[]
 for t in range(L):
  bs.append(b);q=b@E;qs.append(q)
  if t<L-1:
   u=b*E[:,T[:,t]].T;w=u/u.sum(1,keepdims=True);ws.append(w);b=w@A
 Q=np.stack(qs,1); loss=np.sum(P*np.log(np.maximum(P,1e-12)/Q))/(B*L)
 gE=np.zeros_like(E);gA=np.zeros_like(A);gb=np.zeros((B,K))
 for t in range(L-1,-1,-1):
  b=bs[t];gq=-P[:,t]/qs[t]/(B*L);gE+=b.T@gq;gb+=gq@E.T
  if t>0:
   w=ws[t-1];gA+=w.T@gb;gw=gb@A.T;gu=(gw-(gw*w).sum(1,keepdims=True))/qs[t-1][np.arange(B),T[:,t-1],None]
   np.add.at(gE.T,T[:,t-1],gu*bs[t-1]);gb=gu*E[:,T[:,t-1]].T
 gpi=gb.sum(0)
 grads=[v*(g-(g*v).sum(-1,keepdims=True)) for v,g in zip((E,A,pi),(gE,gA,gpi))]
 return loss,grads

def fit(T,P,par,steps=1000,lr=.03,verbose=False):
 m=[np.zeros_like(a) for a in par];v=[np.zeros_like(a) for a in par];start=time.time();best=(np.inf,None)
 for i in range(1,steps+1):
  loss,gs=lossgrad(T,P,par)
  if loss<best[0]:best=(loss,[a.copy() for a in par])
  for j,g in enumerate(gs):
   m[j]=.9*m[j]+.1*g;v[j]=.999*v[j]+.001*g*g;par[j]-=lr*(m[j]/(1-.9**i))/(np.sqrt(v[j]/(1-.999**i))+1e-8)
  if verbose and i%500==0: print(i,round(loss,7),round(time.time()-start,2),flush=True)
 return best[1],best[0]

def em(T,K,steps=100,seed=0):
 rng=np.random.default_rng(seed);B,L=T.shape;V=16
 E=rng.dirichlet(np.full(V,.8),K);A=.80*np.eye(K)+.20*rng.dirichlet(np.ones(K),K);pi=np.full(K,1/K)
 for it in range(steps):
  al=[];zs=[];b=np.broadcast_to(pi,(B,K)).copy()
  for t in range(L):
   w=b*E[:,T[:,t]].T;z=w.sum(1,keepdims=True);w/=z;al.append(w);zs.append(z);b=w@A
  be=np.ones((B,K));gE=np.full_like(E,.03);gA=np.full_like(A,.02)
  for t in range(L-1,-1,-1):
   gam=al[t]*be;gam/=gam.sum(1,keepdims=True);np.add.at(gE.T,T[:,t],gam)
   if t:
    ev=E[:,T[:,t]].T*be;gA+=A*(al[t-1].T@(ev/zs[t]));be=(ev@A.T)/zs[t]
   else:gpi=gam.sum(0)+.02
  E=gE/gE.sum(1,keepdims=True);A=gA/gA.sum(1,keepdims=True);pi=gpi/gpi.sum()
 return [logits(x) for x in (E,A,pi)]
''')
